        dc.b    $0D                                      ; Value of the IAC event timer IacEventTimer when the gear-change IAC starts
BusReqHoldTime:
        dc.b    $00                                      ; Bus request from the body (CcdReceive, PciReceive): hold time (BusReqTimer) of the request flag BusReqFlags bit 4
BusReqThrottleMax:
        dc.b    $00                                      ; Bus request: throttle opening below this value for the request flag to be set
AcCutCoolantOn:
        dc.b    $F4                                      ; A/C cut-out (AcCutLogic): coolant at or above which the A/C is cut
AcCutCoolantOff:
        dc.b    $F1                                      ; A/C cut-out: coolant below which it is allowed again
AcCutRpmHigh:
        dc.b    $FF,$00                                  ; A/C logic: engine rpm above which the A/C is cut (FF00 = off)
AcCycleBattTempMin:
        dc.b    $95                                      ; A/C clutch: battery temperature above this value for the short cycle-time check
AcCycleBattTempMax:
        dc.b    $FE                                      ; A/C clutch: battery temperature below this value for the short cycle-time check
AcCycleTimeMin:
        dc.b    $41                                      ; A/C clutch: clutch state time (AcClutchTimer) needed before the clutch may change in the cycle-time check
AcPressureLowCut:
        dc.b    $00                                      ; A/C clutch: A/C sensor below this value cuts the clutch (low pressure)
AcPressureLowRestore:
        dc.b    $00                                      ; A/C clutch: after a cut, the sensor must rise to this value before the clutch returns
AcPressureHighCut:
        dc.b    $00                                      ; A/C clutch (AcClutchControl): A/C sensor at or above this value cuts the clutch (high pressure); also used by the IAC A/C logic
AcPressureHighRestore:
        dc.b    $00                                      ; A/C clutch: after a cut, the sensor must fall below this value before the clutch returns
AcCoolantMin:
        dc.b    $74                                      ; A/C logic: coolant below which the throttle cut-outs are reset
AcLaunchCutThrottle:
        dc.b    $07                                      ; A/C cut-out 2: throttle at or above this value
AcLaunchCutRpmMax:
        dc.b    $FF                                      ; A/C cut-out 2: below this engine rpm
AcLaunchCutTime:
        dc.b    $04                                      ; A/C cut-out 2: duration (AcLaunchCutTimer); 0 = off
AcLaunchCutThrottleHyst:
        dc.b    $04                                      ; A/C cut-out 2: throttle hysteresis while active
AcLaunchCutSpeedMax:
        dc.b    $08                                      ; A/C cut-out 2: below this vehicle speed
AcLaunchCutSpeedEnd:
        dc.b    $28                                      ; A/C cut-out 2: ends at this vehicle speed
AcWotCutThrottle:
        dc.b    $FF                                      ; A/C cut-out 1: throttle at or above this value
AcWotCutSpeedMax:
        dc.b    $FF                                      ; A/C cut-out 1: below this vehicle speed
AcWotCutThrottleHyst:
        dc.b    $00                                      ; A/C cut-out 1: throttle hysteresis while active
AcWotCutTime:
        dc.b    $06                                      ; A/C cut-out 1: duration (AcWotCutTimer); 0 = off
StarterCutHold:
        dc.b    $00                                      ; Starter control (StarterCut, Options0333 bit 2, probably the starter relay): hold count (StarterCutTimer) after rpm drops
StarterCutRpm:
        dc.b    $00,$00                                  ; Starter control: engine rpm below this value (word) clears the cut flag ControlFlags944 bit 0

;---------------------------------------------------------------------------------------------------
; ResetCoolantInit ($0609): 2D table, 8 points, unsigned
; At reset: IdleRpmRefStart against start coolant temperature
; x: tempc, y: raw (units: docs/en/calibration.md)
; Inputs: StartCoolantTemp2
; Read at $0D888
;---------------------------------------------------------------------------------------------------
ResetCoolantInit:
        dc.b    8,$80                                    ; points, flags
        dc.b    255,255, 255,255, 255,255, 255,255, 255,255, 255,255, 255,255, 255,255 ; x, y

EgrBattTempMin:
        dc.b    $7C                                      ; EGR enable: battery temperature above this value
EgrBattTempMax:
        dc.b    $FE                                      ; EGR enable: battery temperature below this value (once EgrFlags2 bit 3 is set)
EgrStartColdMax:
        dc.b    $84                                      ; At start: EGR stays off (EgrFlags bit 2) at start coolant up to this value
EgrStartWarmMax:
        dc.b    $8F                                      ; At start: EgrStartDelayCoolant applies up to this start coolant
EgrCoolantOn:
        dc.b    $FA                                      ; EGR enable: coolant at or above this value sets EgrFlags bit 4
EgrCoolantOff:
        dc.b    $F5                                      ; EGR enable: coolant at or above this value clears it again (window)
EgrVacuumMin:
        dc.b    $16                                      ; EGR enable: manifold vacuum above this value
EgrVacuumHyst:
        dc.b    $04                                      ; Vacuum hysteresis while EGR is off
EgrMapHyst:
        dc.b    $0A                                      ; MAP hysteresis on EgrMapMinRpm while EGR is off
EgrOnDelay:
        dc.b    $10                                      ; EGR: loops (EgrOnTimer) before EgrFlags bit 1 sets
EgrOffDelay:
        dc.b    $08                                      ; EGR: loops before EgrFlags bit 1 clears

;---------------------------------------------------------------------------------------------------
; EgrThrottleMax ($0626): 2D table, 1 points, unsigned
; EGR enable: throttle limit against vehicle speed while EGR is on
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: VehicleSpeed
; Read at $397BC, $399BE
;---------------------------------------------------------------------------------------------------
EgrThrottleMax:
        dc.b    1,$80                                    ; points, flags
        dc.b    255,1                                    ; x, y

        dc.b    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF

;---------------------------------------------------------------------------------------------------
; EgrThrottleMaxOff ($0638): 2D table, 1 points, unsigned
; As EgrThrottleMax while EGR is off (hysteresis)
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: VehicleSpeed
; Read at $397CC, $399CE
;---------------------------------------------------------------------------------------------------
EgrThrottleMaxOff:
        dc.b    1,$80                                    ; points, flags
        dc.b    255,3                                    ; x, y

        dc.b    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF

;---------------------------------------------------------------------------------------------------
; EgrMapMinRpm ($064A): 2D table, 2 points, unsigned
; EGR enable: MAP must be above this value against engine rpm (plus $0623 while off)
; x: rpm32, y: kpa (units: docs/en/calibration.md)
; Inputs: EngineRpm
; Read at $3977A, $3997C
;---------------------------------------------------------------------------------------------------
EgrMapMinRpm:
        dc.b    2,$80                                    ; points, flags
        dc.b    40,244, 44,79                            ; x, y

        dc.b    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
        dc.b    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF

;---------------------------------------------------------------------------------------------------
; EgrStartDelayCoolant ($066E): 2D table, 1 points, unsigned
; EGR delay after start (EgrStartDelay) against start coolant temperature
; x: tempc, y: raw (units: docs/en/calibration.md)
; Inputs: StartCoolantTemp2
; Read at $396D0, $39898
;---------------------------------------------------------------------------------------------------
EgrStartDelayCoolant:
        dc.b    1,$80                                    ; points, flags
        dc.b    255,64                                   ; x, y

        dc.b    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
FieldControlMode:
        dc.b    $02                                      ; Generator field control mode (ChargeControl, ChargeControl2): 0 = off, 1, or 2 and more select the branch with ThrottleState bit 1
EgrTargetFixed:
        dc.b    $00                                      ; EGR: fixed position target used with EgrMonFlags bit 1 (0 = off)
EgrDutyOverride:
        dc.b    $00                                      ; EGR: when not zero the PID is bypassed (output $067D)
EgrDutyFixed:
        dc.b    $00                                      ; EGR: fixed PWM duty used while EgrDutyOverride is zero and this is not
EgrFlowUpdatePeriod:
        dc.b    $00                                      ; EGR flow estimate: passes between updates (0 = every pass)
EgrFlowFilterRise:
        dc.b    $00,$00                                  ; EGR flow estimate: filter divisor (word) while MAP rises
EgrFlowFilter:
        dc.b    $00,$00                                  ; EGR flow estimate: filter divisor (word) used normally
EgrMapRiseHyst:
        dc.b    $00                                      ; EGR: MAP hysteresis of the rising-MAP state (EgrFlags2 bit 1) against the filtered MAP EgrMapFiltered
EgrExhaustPressRef:
        dc.b    $00                                      ; EGR (EgrControl): reference pressure for the ratio (ref − MAP)/(baro − MAP) looked up in EgrPressureRatio (0 = factor $FF)
EgrPidP:
        dc.b    $00                                      ; EGR PID: proportional gain
EgrPidI:
        dc.b    $00                                      ; EGR PID: integral gain
EgrPidD:
        dc.b    $00                                      ; EGR PID: derivative gain
EgrPidDeadband:
        dc.b    $00                                      ; EGR PID: position error below which the P and I terms are zero
EgrTrackTargetMax:
        dc.b    $00                                      ; EGR position tracking test: target position at or below this value
EgrResultPassCount:
        dc.b    $00                                      ; EGR flow test result: passed tests (EgrResultPasses) before the test counts as passed
EgrZeroDutyMax:
        dc.b    $00                                      ; EGR closed-position check: EGR duty at or below this value (valve commanded closed, not WOT)
EgrZeroDelay:
        dc.b    $00                                      ; EGR closed-position check: delay (EgrZeroTimer) after the valve closes before the position is followed
EgrZeroPositionInit:
        dc.b    $00                                      ; Start value of the learned EGR closed position EgrZeroPos
EgrZeroPosMin:
        dc.b    $00                                      ; EGR closed-position check: followed position below this value fails
EgrZeroPosMax:
        dc.b    $00                                      ; EGR closed-position check: followed position above this value fails (EgrZeroFlags bit 7)
EgrZeroArmCoolant:
        dc.b    $6E                                      ; EGR closed-position check: coolant above this value to arm the check
EgrZeroArmTime:
        dc.b    $00                                      ; EGR closed-position check: time (EgrMonTimer) the arm conditions must hold
EgrZeroArmTarget:
        dc.b    $00                                      ; EGR closed-position check (EgrZeroCheck): target position above this value arms the check (EgrZeroFlags bit 1)
EgrZeroSlewUp:
        dc.b    $00                                      ; EGR closed-position check: largest rise per pass of the followed position
EgrZeroSlewDown:
        dc.b    $00                                      ; EGR closed-position check: largest fall per pass of the followed position EgrZeroPos

;---------------------------------------------------------------------------------------------------
; EgrFlowFilterVacuum ($0695): 2D table, 5 points, unsigned
; EGR flow estimate: filter weight against manifold vacuum (multiplied by rpm)
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: ManifoldVacuum
; Read at $39B00
;---------------------------------------------------------------------------------------------------
EgrFlowFilterVacuum:
        dc.b    5,$80                                    ; points, flags
        dc.b    255,255, 255,255, 255,255, 255,255, 255,255 ; x, y


;---------------------------------------------------------------------------------------------------
; EgrFeedForward ($06A1): 2D table, 10 points, unsigned
; EGR valve: base PWM duty against the position target, added to the PID terms (output to PWMA)
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: EgrTargetPos
; Read at $39C82
;---------------------------------------------------------------------------------------------------
EgrFeedForward:
        dc.b    10,$80                                   ; points, flags
        dc.b    255,255, 255,255, 255,255, 255,255, 255,255, 255,255, 255,255, 255,255 ; x, y
        dc.b    255,255, 255,255                         ; x, y


;---------------------------------------------------------------------------------------------------
; EgrPressureRatio ($06B7): 2D table, 5 points, unsigned
; EGR flow estimate: factor against the ratio ($0684 − MAP)/(baro − MAP), into EgrPressureFactor
; x: raw, y: mult256 (units: docs/en/calibration.md)
; Inputs: ?
; Read at $39A92
;---------------------------------------------------------------------------------------------------
EgrPressureRatio:
        dc.b    5,$80                                    ; points, flags
        dc.b    0,255, 0,255, 0,255, 0,255, 0,255        ; x, y


;---------------------------------------------------------------------------------------------------
; EgrTarget ($06C3): 3D table, 17 rows x 17 columns, unsigned
