        dc.b    166,0, 210,255                           ; x, y

        dc.b    $FF,$FF,$FF,$FF

;---------------------------------------------------------------------------------------------------
; AirTempSparkMapRpm ($1ECB): 3D table, 5 rows x 9 columns, signed
; Spark change for intake air temperature, MAP x rpm (signed), scaled by AirTempSparkFactor
; columns: rpm32, rows: pos256, values: spark (units: docs/en/calibration.md)
; Inputs: result of Lookup2D x EngineRpm
; Read at $1D1D4
;---------------------------------------------------------------------------------------------------
AirTempSparkMapRpm:
        dc.b    5,9,$FF                                  ; rows, columns, signed
        dc.b    17,28,34,39,45,50,75,88,119              ; column axis
        dc.b    0,0,0,0,0,0,0,0,0                        ; row 0
        dc.b    0,0,0,0,0,0,0,0,0                        ; row 1
        dc.b    0,0,-1,-2,-3,-4,-4,-4,-4                 ; row 2
        dc.b    0,0,-2,-4,-6,-8,-8,-8,-8                 ; row 3
        dc.b    0,0,-2,-4,-6,-8,-8,-8,-8                 ; row 4

AfterStartSparkEvents:
        dc.b    $06                                      ; After-start spark retard (AfterStartSpark): crank events (CrankEventCount) before the retard starts
AfterStartRetardBaroMin:
        dc.b    $FF                                      ; After-start spark retard runs at or above this barometric pressure (not at WOT)
AfterStartSparkStepEvents:
        dc.b    $04                                      ; After-start spark retard: events per step of the first ramp
AfterStartSparkStepEvents2:
        dc.b    $04                                      ; After-start spark retard: events per step of the last ramp
AfterStartSparkRpmBand:
        dc.b    $01,$90                                  ; After-start spark retard: ends early in gear when rpm is more than this away from the idle target

;---------------------------------------------------------------------------------------------------
; AfterStartSparkCoolant ($1F0A): 2D table, 10 points, unsigned
; Spark change after start against the coolant temperature at start, into AfterStartSparkStart
; x: tempc, y: spark (units: docs/en/calibration.md)
