        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 1
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 2
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 3
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 4
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 5
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 6
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 7
        dc.b    -1,-1,-1,-1,-1,-1,-1,-1,-1               ; row 8


