        dc.b    $03,$75,$02,$02,$4D,$02,$02,$00,$00,$04,$00,$00,$00,$01,$4D,$00
        dc.b    $0C,$00,$00,$00,$00,$00,$00,$00,$00,$00
CoilOutputValue:
        dc.b    $00                                      ; Isr_GPT_IC4OC5: value written into the output table at $886E for odd steps

