        dc.b    $BA                                      ; Low-voltage monitor: battery voltage at or above this value counts as normal
BattLowSetCount:
        dc.b    $95                                      ; Low-voltage monitor: counts before ChargeMonFlags bit 2 sets
BattLowClearCount:
        dc.b    $19                                      ; Low-voltage monitor: counts before ChargeMonFlags bit 2 clears
BattLowStartTime:
