;---------------------------------------------------------------------------------------------------
; ThermistorCold ($7047): 2D table, 7 points, unsigned
; Thermistor ADC counts to temperature, cold range (-55 to 83 C), used after the pull-up is switched
; x: raw, y: tempc (units: docs/en/calibration.md)
; Inputs: CoolantRaw; AirTempRaw; ?
; Read at $0D85E, $0D8B2, $20B12, $2C254, $2C362, $3248E, $32524
;---------------------------------------------------------------------------------------------------
ThermistorCold:
        dc.b    7,$80                                    ; points, flags
        dc.b    0,211, 83,171, 215,120, 230,110, 241,100, 246,94, 255,73 ; x, y


;---------------------------------------------------------------------------------------------------
; ThermistorHot ($7057): 2D table, 4 points, unsigned
; Thermistor ADC counts to temperature, hot range (13 to 127 C); coolant and intake air
; x: raw, y: tempc (units: docs/en/calibration.md)
; Inputs: CoolantRaw; AirTempRaw
; Read at $0D85E, $0D8B2, $20B12, $2C254, $2C362, $3248E, $32524
;---------------------------------------------------------------------------------------------------
ThermistorHot:
        dc.b    4,$80                                    ; points, flags
        dc.b    66,255, 87,241, 197,181, 255,141         ; x, y


;---------------------------------------------------------------------------------------------------
; Thermistor3Curve ($7061): 2D table, 10 points, unsigned
; ADC counts of a third thermistor input (BatteryTempRaw or BusTempRaw3) to temperature, into Temp3
; x: raw, y: tempc (units: docs/en/calibration.md)
; Inputs: BatteryTempRaw; BusTempRaw3
; Read at $0D928, $2C45C, $2C490
;---------------------------------------------------------------------------------------------------
Thermistor3Curve:
        dc.b    10,$80                                   ; points, flags
        dc.b    0,213, 47,173, 75,158, 100,148, 130,138, 160,128, 189,118, 222,103 ; x, y
        dc.b    241,88, 255,71                           ; x, y


;---------------------------------------------------------------------------------------------------
; Thermistor3CurveAlt ($7077): 2D table, 7 points, unsigned
; Alternative curve for the third thermistor input, chosen by calibration bit $0330.2
; x: raw, y: tempc (units: docs/en/calibration.md)
; Inputs: BatteryTempRaw; BusTempRaw3
; Read at $0D928, $2C45C, $2C490
;---------------------------------------------------------------------------------------------------
Thermistor3CurveAlt:
        dc.b    7,$80                                    ; points, flags
        dc.b    23,228, 40,208, 69,188, 112,168, 211,128, 239,108, 251,88 ; x, y

ChargeVoltsMin:
        dc.b    $D3                                      ; Lower limit of the charging voltage target
ChargeVoltsOffsetMax:
        dc.b    $07                                      ; Upper limit of ChargeVoltsOffset

;---------------------------------------------------------------------------------------------------
; ChargeVoltsBattTemp ($7089): 2D table, 5 points, unsigned
; Charging voltage target (ChargeTargetVolts) against battery temperature, limited by $7087/$7088
; x: tempc, y: volt16 (units: docs/en/calibration.md)
; Inputs: ?
; Read at $2C6E4
;---------------------------------------------------------------------------------------------------
ChargeVoltsBattTemp:
        dc.b    5,$80                                    ; points, flags
        dc.b    110,239, 128,233, 143,228, 158,223, 171,218 ; x, y


;---------------------------------------------------------------------------------------------------
; AcSensorCurve ($7095): 2D table, 2 points, unsigned
; A/C sensor (probably refrigerant pressure): ADC AcSensorRaw to AcSensor
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: AcSensorRaw
; Read at $0D8EE, $2CCFA
;---------------------------------------------------------------------------------------------------
AcSensorCurve:
        dc.b    2,$80                                    ; points, flags
        dc.b    9,0, 240,255                             ; x, y

        dc.b    $FF,$FF,$FF,$FF,$FF,$FF

;---------------------------------------------------------------------------------------------------
; FlexEthanolCurve ($70A1): 2D table, 2 points, unsigned
; Flex-fuel: learned ratio to ethanol content (0-170)
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: TBA
; Read at $2C8A4
;---------------------------------------------------------------------------------------------------
FlexEthanolCurve:
        dc.b    2,$80                                    ; points, flags
        dc.b    27,0, 227,170                            ; x, y

        dc.b    $FF,$FF,$FF,$FF,$FF,$FF

;---------------------------------------------------------------------------------------------------
; FlexSensorCurve ($70AD): 2D table, 8 points, unsigned
; Analog input $0A8E (probably the fuel composition sensor: FlexSensorCheck reports P0176/P0178/P0179 for it) to CatTempFiltered
; x: raw, y: raw (units: docs/en/calibration.md)
; Inputs: FlexSensorRaw
; Read at $2DC98
;---------------------------------------------------------------------------------------------------
FlexSensorCurve:
        dc.b    8,$80                                    ; points, flags
        dc.b    11,175, 24,133, 27,125, 43,100, 74,75, 113,50, 167,25, 209,0 ; x, y


;---------------------------------------------------------------------------------------------------
; DwellRpmScale ($70BF): 2D table, 9 points, unsigned
; Rpm to column position of DwellTime
; x: rpm32, y: pos256 (units: docs/en/calibration.md)
; Inputs: EngineRpm
; Read at $1DB70
;---------------------------------------------------------------------------------------------------
DwellRpmScale:
        dc.b    9,$80                                    ; points, flags
        dc.b    16,0, 63,32, 94,64, 125,96, 156,128, 188,160, 219,192, 250,224 ; x, y
        dc.b    255,255                                  ; x, y


;---------------------------------------------------------------------------------------------------
; DwellVoltsScale ($70D3): 2D table, 9 points, unsigned
; Battery voltage to row position of DwellTime
; x: volt16, y: pos256 (units: docs/en/calibration.md)
; Inputs: BatteryVolts2
; Read at $1DB62
;---------------------------------------------------------------------------------------------------
DwellVoltsScale:
        dc.b    9,$80                                    ; points, flags
        dc.b    81,0, 133,32, 152,64, 172,96, 176,128, 209,160, 228,192, 248,224 ; x, y
        dc.b    255,255                                  ; x, y


;---------------------------------------------------------------------------------------------------
; DwellTime ($70E7): 3D table, 9 rows x 9 columns, unsigned, columns by position 0-255
; Coil dwell against battery voltage and rpm (both as positions)
; columns: pos256, rows: pos256, values: raw (units: docs/en/calibration.md)
; Inputs: LDAA IND8, Y
; Read at $1DB7A
;---------------------------------------------------------------------------------------------------
DwellTime:
        dc.b    9,9,$00                                  ; rows, columns, signed
        dc.b    49,165,192,192,192,192,192,192,192       ; row 0
        dc.b    49,165,192,192,192,192,192,192,192       ; row 1
        dc.b    49,165,192,192,192,192,192,192,192       ; row 2
        dc.b    48,148,192,192,192,192,192,192,192       ; row 3
        dc.b    40,128,184,192,192,192,192,192,192       ; row 4
        dc.b    36,110,157,192,192,192,192,192,192       ; row 5
        dc.b    33,96,138,192,192,192,192,192,192        ; row 6
        dc.b    28,85,123,169,192,192,192,192,192        ; row 7
        dc.b    26,74,108,148,185,192,192,192,192        ; row 8


;---------------------------------------------------------------------------------------------------
; BitCollectMaps ($713B): 29 rows of 32 bytes
; Bit maps for CollectBits: 8 entries of RAM offset, mask and output bit build one status byte (switch inputs for SwitchInputsRead and SwitchBitsCollect, output and fault status bytes for the SCI and bus messages)
;---------------------------------------------------------------------------------------------------
BitCollectMaps:
; map 0 ($713B): used by SciSendByte
        dc.b    $0A,$47,$40,$80                          ; out bit 7 <- SwitchInputs2 & $40 (switch input used by the idle air code (load switch, probably power steering or A/C))
        dc.b    $0A,$47,$80,$40                          ; out bit 6 <- SwitchInputs2 & $80 (switch input used by EquipmentDetect and AcClutchControl (A/C request, probably))
        dc.b    $0A,$46,$01,$20                          ; out bit 5 <- SwitchInputs & $01 (brake switch (BrakeSwitchMonitor, idle, speed damping, purge test))
        dc.b    $0A,$47,$20,$10                          ; out bit 4 <- SwitchInputs2 & $20 (park/neutral switch (gear state, starter cut, park/neutral monitor))
        dc.b    $0A,$47,$08,$08                          ; out bit 3 <- SwitchInputs2 & $08 (speed control switch)
        dc.b    $0A,$47,$10,$04                          ; out bit 2 <- SwitchInputs2 & $10 (speed control switch (on/off, probably))
        dc.b    $0A,$47,$04,$02                          ; out bit 1 <- SwitchInputs2 & $04 (speed control switch (set at reset))
        dc.b    $0A,$47,$01,$01                          ; out bit 0 <- SwitchInputs2 & $01 (speed control switch)
; map 1 ($715B): used by SciSendByte
        dc.b    $0A,$46,$02,$80                          ; out bit 7 <- SwitchInputs & $02 (bit 1)
        dc.b    $10,$00,$08,$40                          ; out bit 6 <- IoInputs0 & $08 (key off, probably: the monitors skip while it is set and CheckPowerDown starts the power-down path)
        dc.b    $79,$07,$80,$20                          ; out bit 5 <- PORTGP & $80 (bit 7)
        dc.b    $10,$00,$04,$10                          ; out bit 4 <- IoInputs0 & $04 (ASD relay output present, probably (AsdRelayCheck, the reference-event code))
        dc.b    $0C,$21,$08,$08                          ; out bit 3 <- AcFlags & $08 (A/C request from the bus (message bit 0 in CcdReceive))
        dc.b    $00,$00,$00,$04                          ; unused
        dc.b    $00,$00,$00,$02                          ; unused
        dc.b    $0A,$47,$02,$01                          ; out bit 0 <- SwitchInputs2 & $02 (speed control switch)
; map 2 ($717B): used by SciSendByte
        dc.b    $09,$44,$02,$80                          ; out bit 7 <- ControlFlags944 & $02 (toggled by ActuatorTestMain, not read)
        dc.b    $09,$43,$40,$40                          ; out bit 6 <- ControlFlags943 & $40 (set while an actuator test step runs (ActuatorTestMain, OutputTestOcFire))
        dc.b    $10,$02,$08,$20                          ; out bit 5 <- IoStatus2 & $08 (bit 3)
        dc.b    $09,$43,$10,$10                          ; out bit 4 <- ControlFlags943 & $10 (ASD relay on, probably: set with bit 3 for the key-on prime (RunModeSwitch), cleared at stall; circuit checks of ASD-powered outputs read it)
        dc.b    $09,$44,$20,$08                          ; out bit 3 <- ControlFlags944 & $20 (output toggled by EgrOutputTest (with ControlFlags943 bit 2), not read)
        dc.b    $09,$43,$08,$04                          ; out bit 2 <- ControlFlags943 & $08 (fuel pump relay on, probably (set and cleared with bit 4))
        dc.b    $09,$44,$04,$02                          ; out bit 1 <- ControlFlags944 & $04 (EGR solenoid on (EgrEnable))
        dc.b    $09,$43,$01,$01                          ; out bit 0 <- ControlFlags943 & $01 (A/C clutch relay on (AcCutLogic); the idle code reads it)
; map 3 ($719B): used by SciSendByte
        dc.b    $09,$44,$02,$80                          ; out bit 7 <- ControlFlags944 & $02 (toggled by ActuatorTestMain, not read)
        dc.b    $09,$43,$40,$40                          ; out bit 6 <- ControlFlags943 & $40 (set while an actuator test step runs (ActuatorTestMain, OutputTestOcFire))
        dc.b    $10,$02,$08,$20                          ; out bit 5 <- IoStatus2 & $08 (bit 3)
        dc.b    $09,$43,$10,$10                          ; out bit 4 <- ControlFlags943 & $10 (ASD relay on, probably: set with bit 3 for the key-on prime (RunModeSwitch), cleared at stall; circuit checks of ASD-powered outputs read it)
        dc.b    $09,$44,$20,$08                          ; out bit 3 <- ControlFlags944 & $20 (output toggled by EgrOutputTest (with ControlFlags943 bit 2), not read)
        dc.b    $09,$43,$08,$04                          ; out bit 2 <- ControlFlags943 & $08 (fuel pump relay on, probably (set and cleared with bit 4))
        dc.b    $10,$13,$04,$02                          ; out bit 1 <- IoCtl13 & $04 (bit 2)
        dc.b    $09,$43,$01,$01                          ; out bit 0 <- ControlFlags943 & $01 (A/C clutch relay on (AcCutLogic); the idle code reads it)
; map 4 ($71BB): used by SciSendByte
        dc.b    $09,$44,$02,$80                          ; out bit 7 <- ControlFlags944 & $02 (toggled by ActuatorTestMain, not read)
        dc.b    $09,$43,$40,$40                          ; out bit 6 <- ControlFlags943 & $40 (set while an actuator test step runs (ActuatorTestMain, OutputTestOcFire))
        dc.b    $10,$02,$08,$20                          ; out bit 5 <- IoStatus2 & $08 (bit 3)
        dc.b    $09,$43,$10,$10                          ; out bit 4 <- ControlFlags943 & $10 (ASD relay on, probably: set with bit 3 for the key-on prime (RunModeSwitch), cleared at stall; circuit checks of ASD-powered outputs read it)
        dc.b    $10,$02,$02,$08                          ; out bit 3 <- IoStatus2 & $02 (bit 1)
