;---------------------------------------------------------------------------------------------------
; EquipmentInit ($0DBCA)
; Called from: Reset
;---------------------------------------------------------------------------------------------------
EquipmentInit:
        BRCLR   >Options0330,#$10,L0DBD4                 ; bit 4: catalyst temperature sensor fitted (CatTempMonitor; sets EquipmentFlags bit 0)
        BSET    <EquipmentFlags,Z,#$01                   ; bit 0: copy of calibration bit $0330.4 at reset; not read
L0DBD4:
        BRCLR   >Options032F,#$08,L0DBDE                 ; bit 3: selects branches in the fuel event, closed-loop timing, idle and flex code
        BSET    <BusTempFlags2,Z,#$20
L0DBDE:
        BRSET   >Options0337,#$01,L0DBEE                 ; bit 0: idle dip kick mode (IdleDipKickMode); also EquipmentInit and EquipmentDetect
        BRCLR   >Options0331,#$08,L0DBEE                 ; bit 3: power steering pressure switch fitted (sets EquipmentFlags bit 2)
        BSET    <EquipmentFlags,Z,#$04                   ; bit 2: power steering pressure switch fitted (calibration bit $0331.3, or EquipmentDetect)
L0DBEE:
        BRCLR   >Options0335,#$08,L0DBF8                 ; bit 3: EGR fitted (EgrMain)
        BSET    <EquipmentFlags,Z,#$02                   ; bit 1: copy of calibration bit $0335.3 at reset; not read
L0DBF8:
        BRCLR   >Options0333,#$01,L0DC02                 ; bit 0: output driver variant (EquipmentInit, QspiOutputStatus)
        BSET    <BusTempFlags2,Z,#$10
L0DC02:
        BRCLR   >Options0333,#$10,L0DC0C                 ; bit 4: flex learning variant (FlexLearnMain, FlexIdleLearn, FlexEstimate)
        BSET    <BusTempFlags2,Z,#$40
L0DC0C:
        BRCLR   >Options0335,#$04,L0DC16                 ; bit 2: EGR spark scaled (EgrSparkScaled); also used by PartThrottleFuelCalc
        BSET    <BusTempFlags2,Z,#$80
L0DC16:
        BRCLR   >Options0333,#$80,L0DC20                 ; bit 7: EVAP purge solenoid fitted
        BSET    <BusTempFlags2,Z,#$08
L0DC20:
        BRCLR   >Options032E,#$04,L0DC2A                 ; bit 2: PCI bus (J1850, probably) instead of CCD: PciReceive / PciPitTick run instead of CcdReceive / CcdTransmit
        BSET    <BusTempFlags2,Z,#$04
L0DC2A:
        BRCLR   >Options032E,#$20,L0DC34                 ; bit 5: transmission controller on the bus (sets EquipmentFlags bit 5)
        BSET    <EquipmentFlags,Z,#$20                   ; bit 5: automatic transmission: calibration bit $032E.5, or the transmission module seen on the bus
L0DC34:
        RTS

;---------------------------------------------------------------------------------------------------
; MainLoop ($0DC36)
;
; Background loop, one pass every 14 PIT ticks (about 12 ms). Each pass runs a fixed list of
; routines, then one sub-loop group chosen by the lowest set bit of MainLoopCounter (group n runs
; every 2^(n+1) passes), then a second fixed list. It then waits for LoopTickCounter to reach $0E,
; calling MeasureLoopTime, clears the counter and starts again.
;---------------------------------------------------------------------------------------------------
MainLoop:
        JSR     ReadAnalogInputs
        JSR     KickWatchdogs
        JSR     HardwareCheck
        JSR     MainLoopCounters
        JSR     UpdateDriveFlags
        JSR     ThrottleInputs
        JSR     BaroUpdate
        JSR     MapHighBusFlag
        JSR     O2SensorChecks
        JSR     ClosedLoopMain
        JSR     SpeedCtlSwitchRead
        JSR     CalcDeadTime
        JSR     CalcEngineRpm
        JSR     PwmC18Main
        JSR     GearStateUpdate
        JSR     IdleControl
        JSR     FanMain
        JSR     IdleStateUpdate
        JSR     AcClutchControl
        JSR     CalcVehicleSpeed
        JSR     ChargeLowMonitor
        JSR     CrankFuel
        JSR     RunModeSwitch
        JSR     SurgeControl
        JSR     MisfireEnableMain
        JSR     ObdMonitorMain
        JSR     CalcLoadValue
        JSR     LdpPurgedCheck
        JSR     KnockEnrichment
        JSR     VacuumLeakMonitor
        JSR     RpmIdleFilter
        JSR     KnockWindowUpdate
        JSR     TempInputs
        LDAA    >MainLoopCounter,Z
        LSRA
        LBCS    L0DD84
        LSRA
        LBCS    L0DD76
        LSRA
        LBCS    L0DD40
        LSRA
        BCS     L0DD2A
        LSRA
        BCS     L0DD12
        LSRA
        BCS     L0DD06
        LSRA
        BCS     L0DD02
        LSRA
        LBCC    L0DDA8
        JSR     SriMileageStore
        JSR     O2ActivityCount
        JSR     FaultPendingAge
        JSR     TransMilRequest
        JSR     NvUpdate
        JSR     BusStatusByte
        LBRA    L0DDA8
L0DD02:
        LBRA    L0DDA8
L0DD06:
        JSR     FlexFaultReport
        JSR     FuelSenderMonitor
        LBRA    L0DDA8
L0DD12:
        JSR     KnockLearnDecayStep
        JSR     ChargeHighMonitor
        JSR     MilLampUpdate
        JSR     FuelSysDelayCount
        JSR     BusTempFlag
        LBRA    L0DDA8
L0DD2A:
        JSR     PciLinkCheck
        JSR     PciRpmTimeout
        JSR     SystemTestRejectCount
        JSR     BatteryLowFlag
        JSR     WotLeanMonitor
        BRA     L0DDA8
L0DD40:
        JSR     SecurityState
        JSR     SkimState
        JSR     SkimTimerTick
        JSR     BusTimeoutCheck
        JSR     BodyTimeoutTick
        JSR     AcPressureSensor
        JSR     FlexSensorCheck
