        JSR     QspiRecover
        JSR     BusReqTimerTick
        JSR     BusStatusBytes
        JSR     PciService
        NOP
        NOP
        NOP
        NOP
        LDAA    <MainLoop053,Z
        TAB
        COMB
        STD     <ResetCheckWord,Z
        JSR     CheckPowerDown
L0DEB8:
        ANDP    #$FF1F
        LDAA    >LoopTickCounter,Z
        JSR     MeasureLoopTime
        CMPA    #$0E
        BCS     L0DEB8
        CLR     >LoopTickCounter,Z
        JMP     MainLoop

