        LDAA    #$2A
L0DF3C:
        STAA    >TCTL1,Z
        LDD     #$7200
        BRCLR   >Options0335,#$04,L0DF4E                 ; bit 2: EGR spark scaled (EgrSparkScaled); also used by PartThrottleFuelCalc
        LDD     #$7218
L0DF4E:
