        BMI     L0F02C
        JSR     EepromSkimRead
        BRA     L0F03C
L0F02C:
        BRSET   >Options032E,#$04,L0F038                 ; bit 2: PCI bus (J1850, probably) instead of CCD: PciReceive / PciPitTick run instead of CcdReceive / CcdTransmit
        JSR     SkimTimerService
        BRA     L0F03C
L0F038:
        JSR     PciStateSet6
L0F03C:
        ANDP    #$FF1F
        RTS

